// GENERATED by scripts/gen-shared.ts from src/lib. Do not edit.
/**
 * Works out which notifications are due right now. Pure: the server gathers the facts, this
 * decides. Every result has an idempotency key so nothing is ever sent twice.
 */
import { londonToIso } from '../time/london.ts'
import { pickMessage, type CopyInput } from './messages.ts'
import { timesOn, toMinutes, type NotifyType, type Rule } from './rules.ts'

const DAY = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
const DAY_MS = 86_400_000
/** Countdown days that get their own push */
export const COUNTDOWN_MILESTONES = [100, 60, 30, 21, 14, 7, 3, 1, 0]
/** Streak lengths (weeks) that get a push */
export const isStreakMilestone = (weeks: number): boolean => weeks > 0 && weeks % 4 === 0

export interface NotifyState {
  /** UTC ISO */
  now: string
  /** How far back a scheduled time still counts as due (covers a missed cron run) */
  lookbackMinutes?: number
  rules: readonly Rule[]
  quiet: { start: string; end: string } | null
  pausedUntil: string | null
  goal: { name: string; date: string } | null
  /** Active plan: workout names per ISO weekday */
  plan: { days: Partial<Record<number, string[]>> } | null
  /** A workout was started today (London) */
  workoutToday: boolean
  /** A workout that's been started but not saved */
  openWorkout: { id: string; name: string | null; startedAt: string } | null
  bodyweightToday: boolean
  protein: { eaten: number; target: number | null }
  /** Workouts saved in the last 12 h that set PBs */
  pbWorkouts: { id: string; name: string | null; pbs: string[] }[]
  /** Weeks in a row the weekly target was hit (up to last week) */
  streakWeeks: number
  /** This week so far, for the Sunday rundown */
  rundown: { week: string; done: number; planned: number | null } | null
  /** Idempotency keys already used */
  sent: ReadonlySet<string>
}

export interface Due {
  type: NotifyType | 'test'
  key: string
  title: string
  body: string
  /** In-app path to open */
  url: string
  /** 'skip': logged but not sent (quiet hours, pause or already done) */
  status: 'send' | 'skip'
  reason?: string
}

/** London calendar date, ISO weekday and minutes past midnight for a UTC time. */
export function londonParts(iso: string): { date: string; weekday: number; minutes: number } {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    weekday: 'short',
    hourCycle: 'h23',
  }).formatToParts(new Date(iso))
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? ''
  return {
    date: `${get('year')}-${get('month')}-${get('day')}`,
    weekday: DAY.indexOf(get('weekday')) + 1,
    minutes: Number(get('hour')) * 60 + Number(get('minute')),
  }
}

/** In quiet hours at this London time? Handles windows past midnight (22:00–07:00). */
export function inQuietHours(minutes: number, quiet: NotifyState['quiet']): boolean {
  if (!quiet) return false
  const s = toMinutes(quiet.start)
  const e = toMinutes(quiet.end)
  if (s === e) return false
  return s < e ? minutes >= s && minutes < e : minutes >= s || minutes < e
}

/** Day number of the Monday starting the week of a YYYY-MM-DD date. */
const weekStart = (d: string) => {
  const n = Math.floor(Date.parse(`${d}T00:00:00Z`) / DAY_MS)
  return n - ((n + 3) % 7)
}

const daysBetween = (from: string, to: string) =>
  Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / DAY_MS)

export function dueNotifications(s: NotifyState): Due[] {
  const now = Date.parse(s.now)
  const lookback = (s.lookbackMinutes ?? 30) * 60_000
  const today = londonParts(s.now)
  const out: Due[] = []
  const goalDays = s.goal ? daysBetween(today.date, s.goal.date) : null
  const goal =
    s.goal && goalDays !== null && goalDays > 0 ? { name: s.goal.name, days: goalDays } : null
  const planned = s.plan?.days[today.weekday] ?? []
  const paused = s.pausedUntil !== null && Date.parse(s.pausedUntil) > now
  const quietNow = inQuietHours(today.minutes, s.quiet)

  /** Is a clock time today (London) due now? */
  const isDue = (time: string) => {
    const t = Date.parse(londonToIso(today.date, time))
    return t <= now && t > now - lookback
  }
  const onDay = (r: Rule) => {
    if (r.days === 'all') return true
    if (r.days === 'custom') return r.weekdays.includes(today.weekday)
    return s.plan ? planned.length > 0 : true
  }

  const add = (
    r: Rule | null,
    type: Due['type'],
    key: string,
    title: string,
    copy: Omit<CopyInput, 'key' | 'tone' | 'goal'> & { goal?: boolean },
    url: string,
    skip?: string,
  ) => {
    if (s.sent.has(key)) return
    const reason = skip ?? (paused ? 'paused' : quietNow ? 'quiet hours' : undefined)
    out.push({
      type,
      key,
      title,
      body: pickMessage({
        ...copy,
        key,
        tone: r?.tone ?? 'mix',
        custom: r?.customMessages,
        goal: copy.goal === false ? null : goal,
      }),
      url,
      status: reason ? 'skip' : 'send',
      reason,
    })
  }

  /** A fixed message (no copy pool). */
  const direct = (type: Due['type'], key: string, title: string, body: string, url: string) => {
    if (s.sent.has(key)) return
    const reason = paused ? 'paused' : quietNow ? 'quiet hours' : undefined
    out.push({ type, key, title, body, url, status: reason ? 'skip' : 'send', reason })
  }

  for (const r of s.rules) {
    if (!r.enabled || (r.pausedUntil && Date.parse(r.pausedUntil) > now)) continue
    switch (r.type) {
      case 'gym': {
        if (!onDay(r)) break
        for (const t of timesOn(r, today.weekday)) {
          if (!isDue(t)) continue
          add(
            r,
            'gym',
            `gym:${today.date}:${t}`,
            'Training today 🏋️',
            { pool: 'gym', vars: {} },
            '/',
            r.skipIfLogged && s.workoutToday ? 'already logged' : undefined,
          )
        }
        for (const t of r.followUps) {
          if (!isDue(t)) continue
          add(
            r,
            'gym',
            `gym:${today.date}:f${t}`,
            'Log it or go ⏰',
            { pool: 'gym_followup', vars: {} },
            s.openWorkout ? `/log/session/${s.openWorkout.id}` : '/',
            s.workoutToday ? 'already logged' : undefined,
          )
        }
        break
      }
      case 'log_session': {
        const w = s.openWorkout
        if (!w) break
        const t = Date.parse(w.startedAt) + r.afterStartMinutes * 60_000
        if (t > now || t <= now - lookback) break
        add(
          r,
          'log_session',
          `log:${w.id}`,
          'Save your workout 📝',
          { pool: 'log_session', vars: { workout: w.name ?? 'your workout' }, goal: false },
          `/log/session/${w.id}`,
        )
        break
      }
      case 'missed_workout': {
        // Only for days the plan has a workout on
        if (!s.plan || !planned.length || (r.days === 'custom' && !onDay(r))) break
        for (const t of r.times) {
          if (!isDue(t)) continue
          add(
            r,
            'missed_workout',
            `missed:${today.date}`,
            'Not trained yet 📅',
            {
              pool: 'missed_workout',
              vars: {
                reschedule: r.suggestReschedule ? reschedule(s.plan, today.weekday) : '',
              },
            },
            '/',
            s.workoutToday ? 'already logged' : undefined,
          )
        }
        break
      }
      case 'protein': {
        if (!onDay(r)) break
        for (const t of r.times) {
          if (!isDue(t)) continue
          const { eaten, target } = s.protein
          const grams =
            target && r.showRemaining
              ? eaten >= target
                ? `Target hit: ${Math.round(eaten)} g today 💪`
                : `${Math.round(target - eaten)} g to go (${Math.round(eaten)} of ${Math.round(target)} g).`
              : 'Had enough protein today?'
          add(
            r,
            'protein',
            `protein:${today.date}:${t}`,
            'Protein check 🥩',
            {
              pool: 'protein',
              vars: { grams },
            },
            '/',
          )
        }
        break
      }
      case 'bodyweight': {
        if (!onDay(r)) break
        const done = r.skipIfLogged && s.bodyweightToday ? 'already logged' : undefined
        for (const t of r.times) {
          if (!isDue(t)) continue
          add(
            r,
            'bodyweight',
            `bodyweight:${today.date}:${t}`,
            'Weigh-in ⚖️',
            {
              pool: 'bodyweight',
              vars: {},
            },
            '/',
            done,
          )
        }
        for (const t of r.followUps) {
          if (!isDue(t)) continue
          add(
            r,
            'bodyweight',
            `bodyweight:${today.date}:f${t}`,
            'Weigh-in ⚖️',
            {
              pool: 'bodyweight_followup',
              vars: {},
            },
            '/',
            s.bodyweightToday ? 'already logged' : undefined,
          )
        }
        break
      }
      case 'celebration': {
        if (r.celebrate.pbs) {
          // Sent as soon as the workout is saved; held (not skipped) during quiet hours
          for (const w of s.pbWorkouts) {
            if (paused || quietNow || !w.pbs.length) continue
            const key = `pb:${w.id}`
            if (s.sent.has(key)) continue
            out.push({
              type: 'celebration',
              key,
              title: w.pbs.length > 1 ? `${w.pbs.length} new PBs 🏆` : 'New PB 🏆',
              body: `${w.pbs.slice(0, 3).join(' · ')}${goal ? ` · ${goal.days} days to ${goal.name}` : ''}`,
              url: `/log/session/${w.id}`,
              status: 'send',
            })
          }
        }
        for (const t of r.times) {
          if (!isDue(t)) continue
          if (r.celebrate.streaks && today.weekday === 1 && isStreakMilestone(s.streakWeeks)) {
            direct(
              'celebration',
              `streak:${today.date}:${s.streakWeeks}`,
              `${s.streakWeeks}-week streak 🔥`,
              `${s.streakWeeks} weeks in a row hitting your plan.${goal ? ` ${goal.days} days to ${goal.name}.` : ''}`,
              '/progress/plan',
            )
          }
          if (r.celebrate.countdown && s.goal && goalDays !== null) {
            if (COUNTDOWN_MILESTONES.includes(goalDays)) {
              direct(
                'celebration',
                `countdown:${s.goal.date}:${goalDays}`,
                goalDays === 0 ? `${s.goal.name} day! ✈️` : `${goalDays} days to ${s.goal.name} ✈️`,
                goalDays === 0
                  ? 'You put the work in. Enjoy it.'
                  : goalDays === 1
                    ? 'Tomorrow. Every session got you here.'
                    : `${goalDays} days left. Stick to the plan and arrive ready.`,
                '/',
              )
            }
          }
        }
        break
      }
      case 'weekly_rundown': {
        const w = s.rundown
        if (!w || !onDay(r)) break
        for (const t of r.times) {
          if (!isDue(t)) continue
          direct(
            'weekly_rundown',
            `rundown:${w.week}`,
            'Your weekly rundown 📊',
            rundownBody(w),
            `/reports/${w.week}`,
          )
        }
        break
      }
      case 'plan_proposal':
        // In-app only
        break
    }
  }
  return out
}

/** "3 of 4 workouts this week. Tap for your 3 things to do next week." */
export function rundownBody(w: NonNullable<NotifyState['rundown']>): string {
  const next = 'Tap for 3 things to do next week.'
  if (w.done === 0) return `No workouts this week. ${next}`
  if (w.planned && w.done >= w.planned)
    return `${w.done} of ${w.planned} workouts, full week 💪 ${next}`
  if (w.planned) return `${w.done} of ${w.planned} workouts this week. ${next}`
  return `${w.done} workout${w.done === 1 ? '' : 's'} this week. ${next}`
}

/** "Tomorrow morning is free." / "Thu is free." / "Fold the key lifts into tomorrow's session." */
export function reschedule(plan: NonNullable<NotifyState['plan']>, weekday: number): string {
  const free = (d: number) => !plan.days[d]?.length
  const tomorrow = (weekday % 7) + 1
  if (free(tomorrow)) return 'Tomorrow morning’s free — do it then?'
  for (let i = 2; i <= 6; i++) {
    const d = ((weekday + i - 1) % 7) + 1
    if (free(d)) return `${DAY[d - 1]} is free — move it there?`
  }
  return 'Fold the key lifts into tomorrow’s session?'
}

/**
 * Weeks in a row (ending last week) with at least `target` workouts.
 * `days` are London dates of workouts with something logged.
 */
export function weeklyStreak(days: readonly string[], target: number, today: string): number {
  if (target <= 0) return 0
  const counts = new Map<number, number>()
  for (const d of days) counts.set(weekStart(d), (counts.get(weekStart(d)) ?? 0) + 1)
  let streak = 0
  for (let w = weekStart(today) - 7; (counts.get(w) ?? 0) >= target; w -= 7) streak++
  return streak
}
